import { Router, type Request, type Response } from "express";
import {
  BoardRow,
  CardRow,
  createBoard,
  createCard,
  deleteBoard,
  deleteCard,
  getBoard,
  getCardsByBoard,
  listBoards,
  updateCardPosition
} from "../db/boards-table";

export const router = Router();

// Get all boards
router.get("/", (req: Request, res: Response) => {
  try {
    const boards = listBoards();
    res.json(boards);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch boards" });
  }
});

// Get a specific board by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    if (!id) {
      return res.status(400).json({ error: "ID is required" });
    }

    const board = getBoard(id);
    if (!board) {
      return res.status(404).json({ error: "Board not found" });
    }

    res.json(board);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch board" });
  }
});

// Create a new board
router.post("/", (req: Request, res: Response) => {
  try {
    const { name } = req.body;
    if (!name || typeof name !== "string") {
      return res.status(400).json({ error: "Name is required and must be a string" });
    }

    const id = Date.now().toString(); // Simple unique ID generation
    createBoard(id, name);

    res.status(201).json({ id, name });
  } catch (error) {
    res.status(500).json({ error: "Failed to create board" });
  }
});

// Delete a board
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    if (!id) {
      return res.status(400).json({ error: "ID is required" });
    }

    const existingBoard = getBoard(id);
    if (!existingBoard) {
      return res.status(404).json({ error: "Board not found" });
    }

    deleteBoard(id);
    res.json({ message: "Board deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete board" });
  }
});

// Get all cards for a specific board
router.get("/:boardId/cards", (req: Request, res: Response) => {
  try {
    const boardId = req.params.boardId;
    if (!boardId) {
      return res.status(400).json({ error: "Board ID is required" });
    }

    const cards = getCardsByBoard(boardId);
    res.json(cards);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch cards" });
  }
});

// Create a new card
router.post("/:boardId/cards", (req: Request, res: Response) => {
  try {
    const boardId = req.params.boardId;
    const { title, description, columnName, position } = req.body;

    if (!boardId || !title || !description || !columnName || position === undefined) {
      return res.status(400).json({ error: "Title, description, column name, and position are required" });
    }

    const cardId = Date.now().toString(); // Simple unique ID generation
    createCard(cardId, boardId, title, description, columnName, position);

    res.status(201).json({ id: cardId, title, description, columnName, position });
  } catch (error) {
    res.status(500).json({ error: "Failed to create card" });
  }
});

// Update card position
router.put("/:cardId/position", (req: Request, res: Response) => {
  try {
    const cardId = req.params.cardId;
    const { columnName, position } = req.body;

    if (!cardId || !columnName || position === undefined) {
      return res.status(400).json({ error: "Card ID, column name, and position are required" });
    }

    const existingCard = getCardById(cardId);
    if (!existingCard) {
      return res.status(404).json({ error: "Card not found" });
    }

    updateCardPosition(cardId, columnName, position);
    res.json({ message: "Card position updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update card position" });
  }
});

// Delete a card
router.delete("/:cardId", (req: Request, res: Response) => {
  try {
    const cardId = req.params.cardId;
    if (!cardId) {
      return res.status(400).json({ error: "Card ID is required" });
    }

    const existingCard = getCardById(cardId);
    if (!existingCard) {
      return res.status(404).json({ error: "Card not found" });
    }

    deleteCard(cardId);
    res.json({ message: "Card deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete card" });
  }
});

// Helper function to get card by ID
function getCardById(id: string): CardRow | null {
  const cards = getCardsByBoard("any-board-id"); // This should be replaced with actual board lookup
  return cards.find(card => card.id === id) || null;
}

