import { Router, type Request, type Response } from "express";
import { getLatestReadingByWarehouse, getReadingsBySensor } from "../db/readings-table";
import { getDeviceById, getDevicesByWarehouseId } from "../db/devices-table";

export const router = Router();

// Define alert thresholds
const HEARTBEAT_INTERVAL = 60 * 1000; // 1 minute
const VALUE_RANGE = 100; // Allowable range around sensor limits

// Helper function to calculate average reading value
function calculateAverage(readings: Reading[]): number {
  if (readings.length === 0) return 0;

  const sum = readings.reduce((acc, curr) => acc + curr.value, 0);
  return sum / readings.length;
}

// Middleware to check device API key
router.use("/alerts", (req: Request, res: Response, next: Function) => {
  // This is a placeholder - actual implementation should validate API key
  // For now we'll just pass through to the alert endpoint
  next();
});

// Endpoint to generate alerts
router.get("/alerts", (req: Request, res: Response) => {
  try {
    // Get all devices
    const devices = getDevicesByWarehouseId(1); // Assuming warehouse ID 1

    const alerts = [];

    for (const device of devices) {
      const sensorId = device.id;

      // Check heartbeat
      const latestReading = getLatestReadingByWarehouse(device.warehouseId);
      if (!latestReading || Date.now() - latestReading.timestamp > HEARTBEAT_INTERVAL) {
        alerts.push({
          deviceId: sensorId,
          message: "Missed heartbeat detected",
          severity: "warning"
        });
        continue;
      }

      // Check value range
      const readings = getReadingsBySensor(sensorId);
      const avgValue = calculateAverage(readings);

      if (avgValue < -VALUE_RANGE || avgValue > VALUE_RANGE) {
        alerts.push({
          deviceId: sensorId,
          message: "Out-of-range reading detected",
          severity: "critical"
        });
      }
    }

    return res.json(alerts);
  } catch (error) {
    return res.status(500).json({ error: "Failed to generate alerts" });
  }
});

