import { Router, type Request, type Response } from "express";
import { getWorkoutsByUserId, insertWorkout } from "../db/workouts-table";
import { getFollowers } from "../db/follows-table";

export const router = Router();

// Get workout feed for a user
router.get("/:userId", (req: Request, res: Response) => {
  const userId = Number(req.params.userId);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  // Get followers of the requested user
  const followers = getFollowers(userId);

  // Collect all workout IDs from followers
  const allWorkoutIds = followers.flatMap(follower => {
    return getWorkoutsByUserId(follower.following_id)
      .map(workout => workout.id);
  });

  // Remove duplicates by converting to Set
  const uniqueWorkoutIds = [...new Set(allWorkoutIds)];

