import { Router, type Request, type Response } from "express";
import { getAllCars, getCarById } from "../db/cars-table";
import { insertBooking, getBookingsByCarId } from "../db/bookings-table";

export const router = Router();

// Check car availability for a date range
router.get("/available-cars", (req: Request, res: Response) => {
  const { startDate, endDate } = req.query;

  // Validate query parameters
  if (!startDate || !endDate) {
    return res.status(400).json({ error: "Start date and end date are required" });
  }

  // Get all cars
  const cars = getAllCars();

  // Filter cars based on availability
  const availableCars = cars.filter(car => {
    const bookings = getBookingsByCarId(car.id);

    // Check if there are any overlapping bookings
    const isAvailable = bookings.every(booking => {
      return booking.startDate > endDate || booking.endDate < startDate;
    });

    return isAvailable;
  });

  return res.json(availableCars);
});

// Create a booking
router.post("/bookings", (req: Request, res: Response) => {
  const { carId, customerId, startDate, endDate } = req.body;

  // Validate request body
  if (!carId || !customerId || !startDate || !endDate) {
    return res.status(400).json({ error: "Car ID, customer ID, start date, and end date are required" });
  }

  // Find the car
  const car = getCarById(Number(carId));

  if (!car) {
    return res.status(404).json({ error: "Car not found" });
  }

  // Check if the car is available during the specified period
  const bookings = getBookingsByCarId(car.id);
  const isAvailable = bookings.every(booking => {
    return booking.startDate > endDate || booking.endDate < startDate;
  });

  if (!isAvailable) {
    return res.status(409).json({ error: "Car is not available for the specified dates" });
  }

  // Create the booking
  insertBooking(Number(carId), Number(customerId), startDate, endDate);

  return res.status(201).json({ message: "Booking created successfully" });
});

