  }
});

// Log stock movement
router.post("/movement", (req: Request, res: Response) => {
  try {
    const { product_id, quantity, movement_type } = req.body;

    if (!product_id || !quantity || !movement_type) {
      return res.status(400).json({ error: "Product ID, quantity, and movement type are required" });
    }

    if (!(movement_type === "in" || movement_type === "out")) {
      return res.status(400).json({ error: "Movement type must be 'in' or 'out'" });
    }

    // Simulate getting SKU from product ID
    // In a real system, this would come from a products table
    const sku = `prod-${product_id}`;

    // Update stock level based on movement
    let newQuantity: number;
    const existingStock = getStockLevelBySku(sku);

    if (existingStock) {
      newQuantity = movement_type === "in" ? existingStock.current_quantity + quantity : existingStock.current_quantity - quantity;
      updateStockLevel(sku, existingStock.location_id, newQuantity, existingStock.reorder_threshold);
    } else {
      // If no existing stock, create new entry
      newQuantity = movement_type === "in" ? quantity : 0;
      updateStockLevel(sku, 1, newQuantity, 10); // Default reorder threshold
    }

    // Log the movement
    logStockMovement(Number(product_id), quantity, movement_type);

    // Recompute reorder status
    const updatedStock = getStockLevelBySku(sku);
    if (updatedStock && updatedStock.current_quantity <= updatedStock.reorder_threshold) {
      // Trigger reordering logic here
      console.log(`Reorder needed for SKU: ${sku}`);
    }

    return res.status(201).json({ message: "Stock movement logged successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to log stock movement" });
  }
});

