import { Router, type Request, type Response } from "express";
import {
  Shift,
  getShifts,
  getShiftById,
  insertShift,
  updateShift,
  deleteShift
} from "../db/shifts-table";
import {
  Signup,
  addSignup,
  getSignupsByShift
} from "../db/signups-table";

export const router = Router();

// Get all shifts
router.get("/", (req: Request, res: Response) => {
  try {
    const shifts: Shift[] = getShifts();
    res.json(shifts);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shifts" });
  }
});

// Get a specific shift by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    const shift: Shift | undefined = getShiftById(id);

    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    res.json(shift);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shift" });
  }
});

// Create a new shift
router.post("/", (req: Request, res: Response) => {
  try {
    const { description, startTime, endTime, volunteerCapacity }: {
      description: string;
      startTime: string;
      endTime: string;
      volunteerCapacity: number;
    } = req.body;

    if (!description || !startTime || !endTime || volunteerCapacity === undefined) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    insertShift(description, startTime, endTime, volunteerCapacity);

    // Fetch the created shift to send back
    const shifts: Shift[] = getShifts();
    const createdShift: Shift | undefined = shifts.find(s => s.description === description);

    if (!createdShift) {
      return res.status(500).json({ error: "Failed to retrieve created shift" });
    }

    res.status(201).json(createdShift);
  } catch (error) {
    res.status(500).json({ error: "Failed to create shift" });
  }
});

// Update a shift
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    const { description, startTime, endTime, volunteerCapacity }: {
      description: string;
      startTime: string;
      endTime: string;
      volunteerCapacity: number;
    } = req.body;

    if (!description || !startTime || !endTime || volunteerCapacity === undefined) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingShift: Shift | undefined = getShiftById(id);

    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    updateShift(id, description, startTime, endTime, volunteerCapacity);

    const updatedShift: Shift | undefined = getShiftById(id);

    if (!updatedShift) {
      return res.status(500).json({ error: "Failed to retrieve updated shift" });
    }

    res.json(updatedShift);
  } catch (error) {
    res.status(500).json({ error: "Failed to update shift" });
  }
});

// Delete a shift
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);

    const existingShift: Shift | undefined = getShiftById(id);

    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    deleteShift(id);

    res.json({ message: "Shift deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete shift" });
  }
});

// Sign up a volunteer for a shift
router.post("/:shiftId/signup/:volunteerId", (req: Request, res: Response) => {
  try {
    const shiftId: number = Number(req.params.shiftId);
    const volunteerId: number = Number(req.params.volunteerId);

    const existingShift: Shift | undefined = getShiftById(shiftId);

    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    const existingSignup: Signup | undefined = getSignupsByShift(shiftId).find(
      signup => signup.volunteerId === volunteerId
    );

    if (existingSignup) {
      return res.status(409).json({ error: "Volunteer already signed up for this shift" });
    }

    addSignup(volunteerId, shiftId);

    res.json({ message: "Volunteer signed up successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to sign up volunteer" });
  }
});

import { Router, type Request, type Response } from "express";
import { db, getClockEventsByEmployeeId, insertClockEvent } from "../db/clock-events-table";

export const router = Router();

// Record a clock event
router.post("/clock-events", (req: Request, res: Response) => {
  const { employeeId, eventType, timestamp }: { employeeId: number, eventType: 'in' | 'out', timestamp: string } = req.body;

  if (!employeeId || !eventType || !timestamp) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    insertClockEvent(employeeId, eventType);
    return res.status(201).json({ message: "Clock event recorded successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to record clock event" });
  }
});

// Get weekly hours for an employee
router.get("/weekly-hours/:employeeId", (req: Request, res: Response) => {
  const employeeId = Number(req.params.employeeId);

  if (isNaN(employeeId)) {
    return res.status(400).json({ error: "Invalid employee ID" });
  }

  try {
    const clockEvents = getClockEventsByEmployeeId(employeeId);

    // Calculate total hours based on clock events
    let totalHours = 0;
    let currentShiftStart: string | null = null;

    clockEvents.sort((a, b) => a.timestamp.localeCompare(b.timestamp));

    for (let i = 0; i < clockEvents.length; i++) {
      const event = clockEvents[i];

      if (event.eventType === 'in') {
        currentShiftStart = event.timestamp;
      } else if (event.eventType === 'out' && currentShiftStart) {
        const shiftDuration = Date.parse(event.timestamp) - Date.parse(currentShiftStart);
        totalHours += shiftDuration / (1000 * 60 * 60); // Convert milliseconds to hours
        currentShiftStart = null;
      }
    }

    return res.json({ totalHours });
  } catch (error) {
    return res.status(500).json({ error: "Failed to calculate weekly hours" });
  }
});

