  }
});

// Create a new reservation
router.post("/reserve", (req: Request, res: Response) => {
  const { employeeId, date, spotNumber }: { employeeId: number, date: string, spotNumber: number } = req.body;

  try {
    // Check if reservation already exists
    const existingReservation = getReservationByEmployeeAndDate(employeeId, date);
